mapper.select:
SELECT * FROM training_study_record
WHERE deleted = 0

    AND course_id = #{courseId}


    AND employee_id = #{employeeId}


    AND completed = #{completed}


    AND (LOWER(employee_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(course_title) LIKE CONCAT('%', LOWER(#{keyword}), '%'))


    AND start_time >= TO_TIMESTAMP(#{startDate} || ' 00:00:00', 'YYYY-MM-DD HH24:MI:SS')


    AND start_time <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')

ORDER BY start_time DESC
